import { Meta, StoryObj } from "@storybook/react";
import { expect, within } from "storybook/test";
import { SummaryTotal } from "./summary-total";
import { ShowcaseLayout, Variant, showcaseParameters } from "@/storybook/preview";

const meta = {
  title: "Primitives/Summary Total",
  component: SummaryTotal,
  parameters: {
    docs: {
      description: {
        component:
          'Bold total row for carts and order summaries. With `type: "price"` it formats the amount in SEK, ' +
          "and when `originalProductSummaryAmount` is set it also renders the products row and the deducted " +
          'discount above the total. With `type: "noPrice"` it renders a dash, for summaries without a ' +
          "known amount yet.",
      },
    },
  },
  argTypes: {
    type: { control: "radio", options: ["price", "noPrice"] },
    labelId: { control: "text" },
  },
  args: {
    labelId: "cartSummary",
    type: "price",
    price: 1299,
    originalProductSummaryAmount: undefined,
  },
} satisfies Meta<typeof SummaryTotal>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await expect(canvas.getByTestId("summary-total")).toHaveTextContent("Summa");
    // Intl formatting uses non-breaking spaces as separators, so match the digits loosely.
    await expect(canvas.getByTestId("summary-total")).toHaveTextContent(/1\s?299\s?kr/);
  },
};

export const VariantTypes: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout title="type (with and without discount)" variantType="other">
      <Variant label="price">
        <SummaryTotal {...args} type="price" price={1299} />
      </Variant>
      <Variant label="price with originalProductSummaryAmount (discount rows)">
        <SummaryTotal {...args} type="price" price={999} originalProductSummaryAmount={1299} />
      </Variant>
      <Variant label="noPrice">
        <SummaryTotal {...args} type="noPrice" />
      </Variant>
    </ShowcaseLayout>
  ),
};
